// ===================== the player's car cut from the reference art: ten frames, five steers x brake =====================
const CAR_REF = { rosso: { meta: {"fw": 188, "fh": 80, "ax": 94, "ay": 78, "bw": 136, "n": 14, "steers": 7, "shift": [-22, -14, -7, 0, 7, 14, 22], "heads": [{"x": 67, "y": 3, "w": 27, "h": 18, "sx": 0, "sy": 80}, {"x": 102, "y": 4, "w": 27, "h": 18, "sx": 81, "sy": 80}], "hw": 27, "hh": 18}, src: 'data:image/png;base64,' } };
const CAR_REF_IMG = {};
// decode the sheets before the game starts; carSprites() uses them when present and the setting allows
function loadRefCars() {
  return Promise.all(Object.keys(CAR_REF).map((id) => new Promise((res) => { const im = new Image(); im.onload = () => { CAR_REF_IMG[id] = im; res(); }; im.onerror = () => res(); im.src = CAR_REF[id].src; })));
}
function refCarSprites(spec) {
  const R = CAR_REF[spec.id], im = CAR_REF_IMG[spec.id]; if (!R || !im) return null;
  const m = R.meta, frames = [];
  // the sheet holds seven nose angles; the game uses five of them: full lock, half lock, straight
  const NS = m.steers || 5, cols = NS === 7 ? [0, 1, 3, 5, 6] : [0, 1, 2, 3, 4];
  for (const s of cols) { frames.push([0, 1].map((b) => { const c = canvas(m.fw, m.fh); c.getContext('2d').drawImage(im, (b * NS + s) * m.fw, 0, m.fw, m.fh, 0, 0, m.fw, m.fh); return [c, c]; })); }
  const shift = (m.shift || [0, 0, 0, 0, 0, 0, 0]), shift5 = cols.map((c) => shift[c] || 0);
  // the two of them, cut out separately: three wind phases each, placed over the cockpit and moved by inertia
  const heads = (m.heads || []).map((h) => ({ x: h.x, y: h.y, frames: [0, 1, 2].map((p) => { const c = canvas(h.w, h.h); c.getContext('2d').drawImage(im, h.sx + p * h.w, h.sy, h.w, h.h, 0, 0, h.w, h.h); return c; }) }));
  return { frames, steers: CAR_STEERS, w: m.fw, h: m.fh, ax: m.ax, ay: m.ay, bw: m.bw, side: null, ref: true, heads, shift: shift5 };
}
